/**
 * The unified top-level application core instance exposed to foreign languages.
 */
public protocol AppCoreEngineProtocol : AnyObject {
    
    /**
     * Adds a bookmark favorite item.
     */
    func addFavorite(name: String, uri: String, iconHint: String, isPinned: Bool, tags: [String]) throws  -> UniFfiFavoriteItem
    
    /**
     * Appends a new tab to a session and makes it active.
     */
    func addWorkspaceTab(sessionIdStr: String, title: String, uri: String) throws  -> String
    
    /**
     * Cancels a transfer job and purges its WAL checkpoint.
     */
    func cancelTransfer(jobIdStr: String) throws 
    
    /**
     * Closes an entire workspace session.
     */
    func closeWorkspaceSession(sessionIdStr: String)  -> Bool
    
    /**
     * Closes a tab within a session.
     */
    func closeWorkspaceTab(sessionIdStr: String, tabIdStr: String) throws 
    
    /**
     * Connects directly to a wireless ADB device at host:port synchronously.
     * Performs authentic CNXN handshake with an explicit 4-second timeout and terminates socket immediately on return.
     */
    func connectWirelessAdb(host: String, port: UInt16?) throws  -> UniFfiDeviceDescriptor
    
    /**
     * Creates a new workspace session and returns its UUID.
     */
    func createWorkspaceSession(name: String, initialUri: String)  -> String
    
    /**
     * Atomically finalizes an active transfer, flushing buffers and moving `.ttpart` to destination.
     */
    func finalizeTransfer(jobIdStr: String) throws  -> String
    
    /**
     * Returns current physical 500ms sliding-window throughput in MB/s.
     */
    func getActiveThroughputMbS()  -> Double
    
    /**
     * Queries real-time snapshot for a transfer job.
     */
    func getTransferProgress(jobIdStr: String)  -> UniFfiTransferJobInfo?
    
    /**
     * Gets details of a session.
     */
    func getWorkspaceSession(sessionIdStr: String)  -> UniFfiWorkspaceSession?
    
    /**
     * Queries connected devices from the local ADB server bridge daemon synchronously.
     * Connects via std::net::TcpStream with an explicit 4-second timeout and terminates socket immediately on return.
     */
    func listAdbDevices() throws  -> [UniFfiDeviceDescriptor]
    
    /**
     * Lists directory contents on a connected ADB or MTP peripheral device synchronously.
     */
    func listDeviceDirectory(serial: String, path: String) throws  -> [DeviceEntry]
    
    /**
     * Lists all bookmarks sorted by order index.
     */
    func listFavorites()  -> [UniFfiFavoriteItem]
    
    /**
     * Lists all transfer jobs sorted by priority.
     */
    func listTransfers()  -> [UniFfiTransferJobInfo]
    
    /**
     * Lists all active workspace sessions.
     */
    func listWorkspaceSessions()  -> [UniFfiWorkspaceSession]
    
    /**
     * Navigates backward in tab history.
     */
    func navigateTabBack(sessionIdStr: String, tabIdStr: String) throws  -> String
    
    /**
     * Navigates forward in tab history.
     */
    func navigateTabForward(sessionIdStr: String, tabIdStr: String) throws  -> String
    
    /**
     * Navigates a tab to a new URI.
     */
    func navigateWorkspaceTab(sessionIdStr: String, tabIdStr: String, uri: String) throws 
    
    /**
     * Pauses an active transfer job.
     */
    func pauseTransfer(jobIdStr: String) throws 
    
    /**
     * Records newly transferred physical chunk bytes.
     */
    func recordTransferChunk(jobIdStr: String, chunkBytes: UInt64) throws  -> UniFfiTransferJobInfo
    
    /**
     * Removes a bookmark favorite item by ID.
     */
    func removeFavorite(idStr: String) throws  -> Bool
    
    /**
     * Resumes a paused transfer job from its latest WAL checkpoint.
     */
    func resumeTransfer(jobIdStr: String) throws  -> UInt64
    
    /**
     * Scans the physical USB bus for connected MTP devices synchronously.
     */
    func scanMtpDevices() throws  -> [UniFfiDeviceDescriptor]
    
    /**
     * Queues a new file transfer job with priority and initial WAL state.
     */
    func submitTransfer(priorityStr: String, sourceUri: String, destinationUri: String, totalBytes: UInt64) throws  -> String
    
    /**
     * Switches the active tab in a session.
     */
    func switchWorkspaceTab(sessionIdStr: String, tabIdStr: String) throws 
    
    /**
     * Streams a physical chunk of data into the active transfer PartWriter.
     */
    func writeTransferChunk(jobIdStr: String, chunkData: Data) throws  -> UInt64
    
}

